{K : Type u_1} →
  [inst : Field K] →
    {n : ℕ} → (Fin n → K) ≃ { p // ¬Erdos85.IncidenceRepair.Incident p Erdos85.IncidenceRepair.infinityHyperplane }

∀ {R : Type u_1} {R₂ : Type u_2} {M : Type u_5} {M₂ : Type u_7} [inst : Semiring R] [inst_1 : Semiring R₂]
  [inst_2 : AddCommMonoid M] [inst_3 : AddCommMonoid M₂] [inst_4 : Module R M] [inst_5 : Module R₂ M₂] {τ₁₂ : R →+* R₂}
  {f : M →ₛₗ[τ₁₂] M₂} {y : M}, (y ∈ f.ker) = (f y = 0)

∀ {K : Type u_1} {L : Type u_2} [inst : Field K] [inst_1 : Field L] (H : K →+ L) (a : K) (u v : L),
  Erdos85.IncidenceRepair.linePullback H a u v =
    { toFun := fun x => u * H x + v * H (a * x), map_zero' := ⋯, map_add' := ⋯ }

∀ {K : Type u_1} [inst : Field K] {n : ℕ} (e : Fin 3 ↪ Fin (n + 1)),
  Erdos85.IncidenceRepair.chartLift e =
    { toFun := fun v j => ∑ i, if e i = j then v i else 0, map_add' := ⋯, map_smul' := ⋯ }

∀ {K : Type u_1} [inst : Field K] {n : ℕ}
  (A : Erdos85.IncidenceRepair.Coordinates K n ≃ₗ[K] Erdos85.IncidenceRepair.Coordinates K n),
  Function.Injective ⇑A.symm

∀ {K : Type u_1} [inst : Field K] {n : ℕ}
  (A : Erdos85.IncidenceRepair.Coordinates K n ≃ₗ[K] Erdos85.IncidenceRepair.Coordinates K n),
  Function.Injective ⇑A.symm.symm

∀ {K : Type u_1} [inst : Field K] {n : ℕ}
  (A : Erdos85.IncidenceRepair.Coordinates K n ≃ₗ[K] Erdos85.IncidenceRepair.Coordinates K n)
  (p : Erdos85.IncidenceRepair.Point K n), Projectivization.map ↑A.symm.symm ⋯ (Projectivization.map ↑A.symm ⋯ p) = p

∀ {K : Type u_1} [inst : Field K] {n : ℕ}
  (A : Erdos85.IncidenceRepair.Coordinates K n ≃ₗ[K] Erdos85.IncidenceRepair.Coordinates K n),
  Erdos85.IncidenceRepair.pointEquiv A =
    { toFun := Projectivization.map ↑A ⋯, invFun := Projectivization.map ↑A.symm ⋯, left_inv := ⋯, right_inv := ⋯ }

∀ {K : Type u_1} [inst : Field K] {n : ℕ}
  (A : Erdos85.IncidenceRepair.Coordinates K n ≃ₗ[K] Erdos85.IncidenceRepair.Coordinates K n)
  (p : Erdos85.IncidenceRepair.Point K n), Erdos85.IncidenceRepair.pointEmbedding (RingHom.id K) A p = A • p

∀ {K : Type u_1} [inst : Field K] {n : ℕ}
  (A B : Erdos85.IncidenceRepair.Coordinates K n ≃ₗ[K] Erdos85.IncidenceRepair.Coordinates K n)
  (F : Erdos85.IncidenceRepair.SourceFlag K n), (A * B) • F = A • B • F

∀ {K : Type u_1} [inst : Field K] {n : ℕ}
  (A B : Erdos85.IncidenceRepair.Coordinates K n ≃ₗ[K] Erdos85.IncidenceRepair.Coordinates K n)
  (F : Erdos85.IncidenceRepair.Frame K n), (A * B) • F = A • B • F

∀ {K : Type u_1} [inst : Field K] {n : ℕ}
  (A : Erdos85.IncidenceRepair.Coordinates K n ≃ₗ[K] Erdos85.IncidenceRepair.Coordinates K n)
  (p : Erdos85.IncidenceRepair.Point K n), Projectivization.map ↑A.symm ⋯ (Projectivization.map ↑A ⋯ p) = p

∀ {K : Type u_1} [inst : Field K] {n : ℕ} (H : Erdos85.IncidenceRepair.Hyperplane K n) (c : K)
  {v : Erdos85.IncidenceRepair.Coordinates K n},
  v ∈ {v | ∑ i, v i * Projectivization.rep H i = 0} → c • v ∈ {v | ∑ i, v i * Projectivization.rep H i = 0}

∀ {R : Type u_1} {R₂ : Type u_2} {M : Type u_5} {M₂ : Type u_7} [inst : Semiring R] [inst_1 : Semiring R₂]
  [inst_2 : AddCommMonoid M] [inst_3 : AddCommMonoid M₂] [inst_4 : Module R M] [inst_5 : Module R₂ M₂] {τ₁₂ : R →+* R₂}
  {f : M →ₛₗ[τ₁₂] M₂} {y : M}, (y ∈ f.ker) = (f y = 0)

∀ {L : Type u_2} [inst : Field L] {n : ℕ}
  (A : Erdos85.IncidenceRepair.Coordinates L n ≃ₗ[L] Erdos85.IncidenceRepair.Coordinates L n)
  (h v : Erdos85.IncidenceRepair.Coordinates L n), (Erdos85.IncidenceRepair.dualCoordinates A) h ⬝ᵥ v = h ⬝ᵥ A.symm v

∀ {L : Type u_2} [inst : Field L] {n : ℕ}
  (A : Erdos85.IncidenceRepair.Coordinates L n ≃ₗ[L] Erdos85.IncidenceRepair.Coordinates L n),
  Erdos85.IncidenceRepair.dualCoordinates (Erdos85.IncidenceRepair.dualCoordinates A) = A

∀ {K : Type u_1} {L : Type u_2} [inst : Field K] [inst_1 : Field L] {n : ℕ}
  (ψ : Erdos85.IncidenceRepair.Hyperplane K n → Erdos85.IncidenceRepair.Hyperplane L n) (i : Fin n),
  Erdos85.IncidenceRepair.pencilCoordinate ψ i = Erdos85.IncidenceRepair.globalCoordinate ψ i.succ ⋯

∀ {K : Type u_1} {L : Type u_2} [inst : Field K] [inst_1 : Field L] {n : ℕ}
  (ψ : Erdos85.IncidenceRepair.Hyperplane K n → Erdos85.IncidenceRepair.Hyperplane L n) (σ : K →+* L)
  (A : Erdos85.IncidenceRepair.Coordinates L n ≃ₗ[L] Erdos85.IncidenceRepair.Coordinates L n),
  Erdos85.IncidenceRepair.affineHyperplaneErrors ψ σ A =
    Nat.card
      { H // H ≠ Erdos85.IncidenceRepair.infinityHyperplane ∧ ψ H ≠ Erdos85.IncidenceRepair.hyperplaneEmbedding σ A H }

∀ {K : Type u_1} [inst : Field K] [Finite K] {n : ℕ} (R : Erdos85.IncidenceRepair.Point K n → Prop),
  Nat.card { p // ¬Erdos85.IncidenceRepair.Incident p Erdos85.IncidenceRepair.infinityHyperplane ∧ R p } =
    Nat.card { x // R (Erdos85.IncidenceRepair.affinePoint x) }

∀ {K : Type u_1} {L : Type u_2} [inst : Field K] [inst_1 : Field L] {n : ℕ}
  (φ : Erdos85.IncidenceRepair.Point K n → Erdos85.IncidenceRepair.Point L n)
  (ψ : Erdos85.IncidenceRepair.Hyperplane K n → Erdos85.IncidenceRepair.Hyperplane L n),
  Erdos85.IncidenceRepair.brokenFlags φ ψ =
    Nat.card { pH // Erdos85.IncidenceRepair.Incident pH.1 pH.2 ∧ ¬Erdos85.IncidenceRepair.Incident (φ pH.1) (ψ pH.2) }

∀ {K : Type u_1} {L : Type u_2} [inst : Field K] [inst_1 : Field L] {n : ℕ}
  (φ Gp : Erdos85.IncidenceRepair.Point K n → Erdos85.IncidenceRepair.Point L n)
  (ψ Gh : Erdos85.IncidenceRepair.Hyperplane K n → Erdos85.IncidenceRepair.Hyperplane L n),
  Erdos85.IncidenceRepair.repairDistance φ Gp ψ Gh = Nat.card { p // φ p ≠ Gp p } + Nat.card { H // ψ H ≠ Gh H }

∀ {K : Type u_1} {L : Type u_2} [inst : Field K] [inst_1 : Field L] {n : ℕ} {e : Fin 3 ↪ Fin (n + 1)}
  {φ : Erdos85.IncidenceRepair.Point K n → Erdos85.IncidenceRepair.Point L n}
  {ψ : Erdos85.IncidenceRepair.Hyperplane K n → Erdos85.IncidenceRepair.Hyperplane L n},
  Erdos85.IncidenceRepair.ChartBase e φ ψ →
    ∀ k ∉ Set.range ⇑e,
      ψ (Erdos85.IncidenceRepair.coordinateHyperplane k) = Erdos85.IncidenceRepair.coordinateHyperplane k

